e-items:center;align-content:center;gap:10px}.loader-mark,.onboard-symbol{width:64px;height:64px;border-radius:22px;background:linear-gradient(145deg,var(--brand),#517d6e);color:#fff;display:grid;place-items:center;font:700 34px Georgia,serif}.loading p{color:var(--muted)}
